<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>2048</title>
<style>
body{
  margin:0;
  background:#121212;
  color:white;
  font-family:sans-serif;
  display:flex;
  flex-direction:column;
  align-items:center;
  height:100vh;
}
#header{margin-top:20px;margin-bottom:10px;}
#board{
  width:400px;height:400px;
  background:#333;
  border-radius:8px;
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:5px;
  padding:5px;
}
.tile{background:#777;border-radius:4px;display:flex;align-items:center;justify-content:center;font-size:2rem;font-weight:bold;}
#score{
  margin-top:10px;
  font-size:1.2rem;
}
button{
  margin-top:15px;padding:8px 16px;background:#444;color:white;border:none;border-radius:4px;
}
</style>
</head>
<body>
<div id="header">
  <div id="score">Score: 0</div>
  <button id="reset">New Game</button>
</div>
<div id="board"></div>

<script>
(() => {
const size=4;
let boardArray=[];
let curScore=0;

function createBoard(){
  const b=document.getElementById('board');
  b.innerHTML='';
  for(let r=0;r<size;r++){
    for(let c=0;c<size;c++){
      const div=document.createElement('div');
      div.className='tile';
      div.dataset.r=r;div.dataset.c=c;
      b.appendChild(div);
    }
  }
}
function updateBoard(){
  const tiles=document.querySelectorAll('.tile');
  let i=0;
  for(let r=0;r<size;r++){
    for(let c=0;c<size;c++){
      const val=boardArray[r][c];
      const t=tiles[i++];
      t.textContent=val?val:'';
      t.style.background=val?colorFor(val):'#777';
    }
  }
  document.getElementById('score').textContent='Score: '+curScore;
}
function colorFor(v){
  const colors={2:'#eee4da',4:'#ede0c8',8:'#f2b179',16:'#f59563',
                32:'#f67c5f',64:'#f65e3b',128:'#edcf72',256:'#edcc61',
                512:'#edc850',1024:'#edc53f',2048:'#edc22e'};
  return colors[v]||'#3c3a32';
}
function spawn(){
  const empties=[];
  for(let r=0;r<size;r++)for(let c=0;c<size;c++)
    if(boardArray[r][c]==0)empties.push([r,c]);
  if(empties.length===0)return;
  const [r,c]=empties[Math.floor(Math.random()*empties.length)];
  boardArray[r][c]=Math.random()<0.9?2:4;
}
function reset(){
  curScore=0;
  boardArray=Array.from({length:size},()=>Array(size).fill(0));
  spawn();spawn();
  updateBoard();
}
function move(dir){
  let moved=false;
  const merged=new Array(size).fill(false);
  const delta={left:[0,-1],right:[0,1],up:[-1,0],down:[1,0]};
  const [dr,dc]=delta[dir];
  const range=Array.from({length:size},(_,i)=>i);
  const order = dir==='right' || dir==='down'?range.reverse():range;
  for(const r of order){
    for(const c of order){
      if(boardArray[r][c]==0)continue;
      let nr=r+dr,nc=c+dc;
      while(nr>=0&&nr<size&&nc>=0&&nc<size){
        if(boardArray[nr][nc]==0){nr+=dr;nc+=dc;}
        else break;
      }
      const targetR=nr-dr, targetC=nc-dc;
      if(targetR===r && targetC===c)continue;
      if(boardArray[targetR][targetC]==boardArray[r][c] && !merged[targetR]){
        boardArray[targetR][targetC]*=2;
        curScore+=boardArray[targetR][targetC];
        merged[targetR]=true;
        boardArray[r][c]=0;
        moved=true;
      }else{
        if(targetR!==r || targetC!==c){
          boardArray[targetR][targetC]=boardArray[r][c];
          boardArray[r][c]=0;
          moved=true;
        }
      }
    }
  }
  if(moved)spawn();
  updateBoard();
  return moved;
}
window.game={size,reset,move,board:()=>JSON.parse(JSON.stringify(boardArray)),setBoard:(arr)=>{boardArray=JSON.parse(JSON.stringify(arr));updateBoard();},score:()=>curScore};

createBoard();reset();

document.addEventListener('keydown',e=>{
  const dirs={'ArrowLeft':'left','ArrowRight':'right','ArrowUp':'up','ArrowDown':'down'};
  if(dirs[e.key]){ e.preventDefault(); window.game.move(dirs[e.key]); }
});
document.getElementById('reset').addEventListener('click',window.game.reset);
})();
</script>
</body>
</html>
